    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(v,bg):
    h=len(v); w=len(v[0])
    from collections import deque
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for r in range(h):
        for c in range(w):
            if v[r][c]==bg and ((r==0 or r==h-1 or c==0 or c==w-1) or (v[r-1][c]==bg or v[r+1][c]==bg or v[r][c-1]==bg or v[r][c+1]==bg)):
                continue  # seed region that touches border OR adjacent bg
            seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and v[nr][nc]==bg and not seen[nr][nc]:
                seen[nr][nc]=True; q.append((nr,nc))
    ans=[row[:] for row in v]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if v[r][c]==bg and not seen[r][c]:
                ans[r][c]=4
    return ans
